import{_ as p,a0 as l,w as o,s as h,ao as d,I as t,x as a,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用 Linux 实用程序 gPhoto2 备份手机存储 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 实用程序 gPhoto2 备份手机存储 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 实用程序 gPhoto2 备份手机存储 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 实用程序 gPhoto2 备份手机存储 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200701 Back up your phone-s storage with this Linux utility","title":"使用 Linux 实用程序 gPhoto2 备份手机存储","tag":"202007","desc":""},"relativePath":"202007/20200701 Back up your phone-s storage with this Linux utility.md","filePath":"[post].md"}'),r={name:"202007/20200701 Back up your phone-s storage with this Linux utility.md"};function g(c,s,u,k,b,f){const e=l("Link");return o(),h("div",null,[s[15]||(s[15]=d(`<h1 id="使用-linux-实用程序-gphoto2-备份手机存储" tabindex="-1">使用 Linux 实用程序 gPhoto2 备份手机存储 <a class="header-anchor" href="#使用-linux-实用程序-gphoto2-备份手机存储" aria-label="Permalink to “使用 Linux 实用程序 gPhoto2 备份手机存储”">​</a></h1><blockquote><p>尽情地拍照吧，gphoto2 能够方便、快速地将照片从你的设备传输到 Linux 计算机上。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202007/14/170729pzljppapojy44ro4.jpg" alt=""></p><p>移动设备的最大缺点之一就是其将数据从设备传输到计算机很困难。移动设备在这一缺点上有着悠久的历史。早期的移动设备，如 Pilot 和掌上电脑 PDA 设备，需要使用特殊的同步软件来传输数据（你必须小心翼翼地做这件事，因为你的设备可能会因为电池耗尽而导致数据永久丢失）；旧版 iPod 只提供特定平台的界面。现代移动设备默认将你的数据发送到在线帐户，以便你可以在计算机上再次下载。</p><p>好消息——如果你正在运行 Linux，你可以使用 <code>gphoto2</code> 命令与移动设备进行连接。<code>gphoto2</code> 最初是作为一种与数码相机通信的方式而开发的，那时的数码相机只有传统的相机功能，现在的 <code>gphoto2</code> 可以和许多不同种类的移动设备通讯。别让这个名字骗了你，它可以处理所有类型的文件，而不仅仅是照片。更棒的是，它可以编写脚本、很灵活、并且比大多数 GUI 界面功能强大得多。</p><p>如果你曾经为在计算机和移动设备之间同步数据而苦恼，请了解一下 <code>gphoto2</code>。</p><h3 id="安装-gphoto2" tabindex="-1">安装 gPhoto2 <a class="header-anchor" href="#安装-gphoto2" aria-label="Permalink to “安装 gPhoto2”">​</a></h3><p>很可能你的 Linux 系统已经安装了 libgphoto2，因为它是与移动设备连接的一个关键库，但你可能还需要安装命令 <code>gphoto2</code>，该命令可能在你的存储库中。</p><p>在 Fedora 或 RHEL 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install gphoto2</span></span></code></pre></div><p>在 Debian 或 Ubuntu 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install gphoto2</span></span></code></pre></div><h3 id="验证兼容性" tabindex="-1">验证兼容性 <a class="header-anchor" href="#验证兼容性" aria-label="Permalink to “验证兼容性”">​</a></h3><p>若要确认你的移动设备是否受支持，请使用 <code>--list-cameras</code>，通过管道传输到 <code>less</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gPhoto2 --list-cameras | less</span></span></code></pre></div><p>或者你可以通过管道把它传送到 <code>grep</code> 来搜索一个词。例如，如果你有三星 Galaxy，则使用 <code>grep</code>，并通过选项 <code>-i</code> 关闭区分大小写：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --list-cameras | grep -i galaxy</span></span>
<span class="line"><span>  &quot;Samsung Galaxy models (MTP)&quot;</span></span>
<span class="line"><span>  &quot;Samsung Galaxy models (MTP+ADB)&quot;</span></span>
<span class="line"><span>  &quot;Samsung Galaxy models Kies mode&quot;</span></span></code></pre></div><p>这证实了三星 Galaxy 设备支持通过 MTP 连接和通过 ADB 连接 MTP。</p><p>如果你没有在列表中找到自己的移动设备，你仍然可以尝试使用 <code>gphoto2</code>，可能你的设备在列表中使用了不同的称呼。</p><h3 id="查找移动设备" tabindex="-1">查找移动设备 <a class="header-anchor" href="#查找移动设备" aria-label="Permalink to “查找移动设备”">​</a></h3><p>要使用 gPhoto2，首先必须将移动设备插入计算机，设置为 MTP 模式，并且授予计算机与它交互的权限。这通常需要在你的移动设备上操作，往往是在屏幕上按下一个按钮，以允许其文件系统被刚刚连接的计算机访问。</p><p><img src="https://opensource.com/sites/default/files/uploads/gphoto2-mtp-allow.jpg" alt="Screenshot of allow access message" title="Screenshot of allow access message"></p><p>如果你不授权电脑访问移动设备，那么 gPhoto2 可以检测到你的移动设备，但它不能与之交互。</p><p>要确保计算机检测到你连接的移动设备，请使用 <code>--auto-detect</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --auto-detect</span></span>
<span class="line"><span>Model                       Port</span></span>
<span class="line"><span>---------------------------------------</span></span>
<span class="line"><span>Samsung Galaxy models (MTP) usb:002,010</span></span></code></pre></div><p>如果你的移动设备没有被检测到，请先检查数据线，然后检查你的设备是否配置为通过 MTP、ADB 或其它 gPhoto2 支持的协议连接，如 <code>--list-cameras</code> 所示。</p><h3 id="查询你的设备支持的特性" tabindex="-1">查询你的设备支持的特性 <a class="header-anchor" href="#查询你的设备支持的特性" aria-label="Permalink to “查询你的设备支持的特性”">​</a></h3><p>对于现代设备，通常有过多的潜在功能，但并非所有移动设备都支持这些功能。你可以用 <code>--abilities</code> 选项来确定自己的移动设备支持哪些功能。我觉得结果看起来直观。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --abilities</span></span>
<span class="line"><span>Abilities for camera            : Samsung Galaxy models (MTP)</span></span>
<span class="line"><span>Serial port support             : no</span></span>
<span class="line"><span>USB support                     : yes</span></span>
<span class="line"><span>Capture choices                 : Capture not supported by driver</span></span>
<span class="line"><span>Configuration support           : no</span></span>
<span class="line"><span>Delete selected files on camera : yes</span></span>
<span class="line"><span>Delete all files on camera      : no</span></span>
<span class="line"><span>File preview (thumbnail) support: no</span></span>
<span class="line"><span>File upload support             : yes</span></span></code></pre></div><p>如果只连接一个设备，那么不需要指定查询的设备。但是，如果连接了多个 gPhoto2 可以与之交互的设备，则可以通过端口、相机型号或 usbid 指定设备。</p><h3 id="与你的移动设备交互" tabindex="-1">与你的移动设备交互 <a class="header-anchor" href="#与你的移动设备交互" aria-label="Permalink to “与你的移动设备交互”">​</a></h3><p>如果你的设备支持拍摄功能，则可以从计算机调用你的摄像头来获取媒体。例如，要拍摄照片：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --capture-image</span></span></code></pre></div><p>要拍摄照片并立即将其传输到连接的计算机：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --capture-image-and-download</span></span></code></pre></div><p>你也可以录制视频和声音。如果连接了多个拍摄设备，可以按端口、相机型号或 usbid 指定要使用的设备：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --camera &quot;Samsung Galaxy models (MTP)&quot; \\</span></span>
<span class="line"><span>--capture-image-and-download</span></span></code></pre></div><h3 id="文件和文件夹" tabindex="-1">文件和文件夹 <a class="header-anchor" href="#文件和文件夹" aria-label="Permalink to “文件和文件夹”">​</a></h3><p>要想更加智能地管理移动设备上的文件，你需要了解 gPhoto2 连接的文件系统的结构。</p><p>你可以使用 <code>--get-folders</code> 选项查看可用文件夹：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --list-folders</span></span>
<span class="line"><span>There are 2 folders in folder &#39;/&#39;.                                            </span></span>
<span class="line"><span> - store_00010001</span></span>
<span class="line"><span> - store_00020002</span></span>
<span class="line"><span>There are 0 folders in folder &#39;/store_00010001&#39;.</span></span>
<span class="line"><span>There are 0 folders in folder &#39;/store_00020002&#39;.</span></span></code></pre></div><p>每个文件夹代表设备上的一个存储单元。在本例中，<code>store_00010001</code> 是内部存储器，<code>store_00020002</code> 是 SD 卡，这可能与你的设备的结构不同。</p><h3 id="获取文件" tabindex="-1">获取文件 <a class="header-anchor" href="#获取文件" aria-label="Permalink to “获取文件”">​</a></h3><p>现在你知道了设备的文件夹布局，就可以从设备获取照片了。你可以使用许多不同的选项，具体取决于你想从设备中获取什么。</p><p>如果你知道绝对路径，则可以获取指定的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --get-file IMG_0001.jpg --folder /store_00010001/myphotos</span></span></code></pre></div><p>你可以同时获得所有的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --get-all-files --folder /store_00010001/myfiles</span></span></code></pre></div><p>你可以只获取音频文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gphoto2 --get-all-audio-data --folder /store_00010001/mysounds</span></span></code></pre></div><p>gPhoto2 还有其他的选择，其中大多数取决于你连接的设备和使用协议是否支持。</p><h3 id="上传文件" tabindex="-1">上传文件 <a class="header-anchor" href="#上传文件" aria-label="Permalink to “上传文件”">​</a></h3><p>现在你知道了潜在的目标文件夹，就可以将文件从计算机上传到你的设备。例如，假设有一个名为 <code>example.epub</code> 的文件在当前目录中，你可以使用 <code>--upload-file</code> 选项和 <code>--folder</code> 选项将文件发送到设备并指定要上传到的目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --upload file example.epub \\</span></span>
<span class="line"><span>--folder store_00010001</span></span></code></pre></div><p>如果你希望将多个文件上传到同一个位置，你可以在设备上创建一个目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --mkdir books \\</span></span>
<span class="line"><span>--folder store_00010001</span></span>
<span class="line"><span>$ gphoto2 --upload-file *.epub \\</span></span>
<span class="line"><span>--folder store_00010001/books</span></span></code></pre></div><h3 id="列出文件" tabindex="-1">列出文件 <a class="header-anchor" href="#列出文件" aria-label="Permalink to “列出文件”">​</a></h3><p>若要查看设备上的文件，请使用 <code>--list-files</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gphoto2 --list-files --folder /store_00010001</span></span>
<span class="line"><span>There is 1 file in folder &#39;/store_00010001&#39;</span></span>
<span class="line"><span>#1     example.epub 17713 KB application/x-unknown</span></span>
<span class="line"><span>$ gphoto2 --list-files --folder /store_00010001/books</span></span>
<span class="line"><span>There is 1 file in folder &#39;/store_00010001&#39;</span></span>
<span class="line"><span>#1    example0.epub 17713 KB application/x-unknown</span></span>
<span class="line"><span>#2    example1.epub 12264 KB application/x-unknown</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><h3 id="探索你的使用方式" tabindex="-1">探索你的使用方式 <a class="header-anchor" href="#探索你的使用方式" aria-label="Permalink to “探索你的使用方式”">​</a></h3><p>gPhoto2 的大部分功能取决于你的设备，因此不同用户的体验可能不尽相同。在 <code>gphoto2 --help</code> 中列出了许多操作供你探索。使用gPhoto2，再也不用费劲把文件从你的设备传输到电脑上了！</p><p>这些开源图片库能够帮助你组织文件，并让的图片看起来很棒。</p><hr>`,63)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/20/7/gphoto2-linux"},{default:n(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/20/7/gphoto2-linux",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:n(()=>[...s[2]||(s[2]=[a("Seth Kenlon",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),i(e,{href:"https://github.com/summer2233"},{default:n(()=>[...s[4]||(s[4]=[a("summer2233",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=p(r,[["render",g]]);export{y as __pageData,C as default};
